// Generated by gst-extension/build.js from index.html. Edit index.html, then run: node gst-extension/build.js
(function(){
  const root = document.currentScript.parentElement;

  // ---------- Page nav ----------
  root.querySelectorAll('.app-nav-item').forEach(item=>{
    item.addEventListener('click', ()=>{
      root.querySelectorAll('.app-nav-item').forEach(i=>i.classList.remove('active'));
      item.classList.add('active');
      const page = item.getAttribute('data-page');
      ['size','profit','gst'].forEach(p=>root.querySelector('#page-'+p).classList.toggle('hidden', page!==p));
    });
  });

  // ---------- Shared helpers ----------
  function norm(s){ return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,''); }
  function findHeaderRow(rows, requiredGroups){
    for(let i=0;i<Math.min(rows.length,20);i++){
      const cells = rows[i].map(c=>norm(c));
      const ok = requiredGroups.every(group=>{
        const tokens = group.map(norm);
        return cells.some(cell=> tokens.every(t=>cell.includes(t)));
      });
      if(ok) return i;
    }
    return -1;
  }
  function colIndex(headerRow, group){
    const tokens = group.map(norm);
    for(let i=0;i<headerRow.length;i++){
      const cell = norm(headerRow[i]);
      if(tokens.every(t=>cell.includes(t))) return i;
    }
    return -1;
  }
  function parseCSVFile(file){
    return new Promise((resolve,reject)=>{
      const reader = new FileReader();
      reader.onload = e=>{ try{ resolve(Papa.parse(e.target.result,{skipEmptyLines:true}).data); }catch(err){reject(err);} };
      reader.onerror = reject;
      reader.readAsText(file);
    });
  }
  function fmtMoney(n){ return '\u20b9' + Math.round(n).toLocaleString('en-IN'); }
  function wireDrop(dropEl, inputEl, onFiles, multi){
    dropEl.addEventListener('click', ()=>inputEl.click());
    inputEl.addEventListener('change', e=>{ if(e.target.files.length) onFiles(e.target.files); });
    ['dragover','dragenter'].forEach(ev=>dropEl.addEventListener(ev, e=>{e.preventDefault(); dropEl.classList.add('drag');}));
    ['dragleave','drop'].forEach(ev=>dropEl.addEventListener(ev, e=>{e.preventDefault(); dropEl.classList.remove('drag');}));
    dropEl.addEventListener('drop', e=>{ if(e.dataTransfer.files.length) onFiles(e.dataTransfer.files); });
  }
  function sortableTable(headEl, bodyEl, footEl, columns, getData, renderRow, renderFoot, initialSort){
    let sort = {...initialSort};
    function draw(){
      headEl.innerHTML = columns.map(c=>{
        const arrow = sort.key===c.key ? (sort.dir===1?'&#9650;':'&#9660;') : '';
        return `<th data-key="${c.key}">${c.label} <span class="arrow">${arrow}</span></th>`;
      }).join('');
      headEl.querySelectorAll('th').forEach(th=>{
        th.addEventListener('click', ()=>{
          const key = th.getAttribute('data-key');
          if(sort.key===key) sort.dir *= -1; else sort = {key, dir:-1};
          draw();
        });
      });
      const data = [...getData()].sort((a,b)=>{
        const av=a[sort.key], bv=b[sort.key];
        if(typeof av === 'string') return av.localeCompare(bv)*sort.dir;
        return ((av||0)-(bv||0))*sort.dir;
      });
      bodyEl.innerHTML = data.map(renderRow).join('');
      if(footEl) footEl.innerHTML = renderFoot(getData());
    }
    return {draw};
  }

  /* =========================================================
     SIZE SUMMARY TOOL
  ========================================================= */
  (function(){
    let ordersFile = null;
    let picklistFiles = [];
    let activeTab = 'csv';

    root.querySelectorAll('[data-szTab]').forEach(tab=>{
      tab.addEventListener('click', ()=>{
        root.querySelectorAll('[data-szTab]').forEach(t=>t.classList.remove('active'));
        tab.classList.add('active');
        activeTab = tab.getAttribute('data-szTab');
        root.querySelector('#sz-tabCsv').classList.toggle('hidden', activeTab!=='csv');
        root.querySelector('#sz-tabPicklist').classList.toggle('hidden', activeTab!=='picklist');
      });
    });

    const fnameO = root.querySelector('#sz-fnameOrders');
    wireDrop(root.querySelector('#sz-dropOrders'), root.querySelector('#sz-fileOrders'), files=>{
      ordersFile = files[0]; fnameO.textContent = files[0].name;
    });

    const listEl = root.querySelector('#sz-picklistFiles');
    function renderPicklistFiles(){
      listEl.innerHTML = picklistFiles.map((p,i)=>`
        <div class="fileitem"><span>${p.file.name}</span><span>
          <span class="status ${p.status==='done'?'done':p.status==='error'?'err':''}">${p.status}</span>
          <span class="remove" data-i="${i}">&times;</span></span></div>`).join('');
      listEl.querySelectorAll('.remove').forEach(el=>{
        el.addEventListener('click', ()=>{ picklistFiles.splice(parseInt(el.getAttribute('data-i'),10),1); renderPicklistFiles(); });
      });
    }
    wireDrop(root.querySelector('#sz-dropPicklist'), root.querySelector('#sz-filePicklist'), files=>{
      Array.from(files).forEach(f=>picklistFiles.push({file:f, status:'pending'}));
      renderPicklistFiles();
    });

    function bucketOf(sizeRaw){
      let s = String(sizeRaw||'').trim().replace(/\s*alterable\s*/i,'').trim();
      const sLower = s.toLowerCase().replace(/\s+/g,'');
      if(sLower.includes('30-34')) return 'XL';
      if(sLower.includes('36-40')) return 'XXL';
      const up = s.toUpperCase();
      if(up==='L'||up==='26'||up==='28'||up==='30') return 'L';
      if(up==='XL'||up==='32'||up==='34') return 'XL';
      if(up==='XXL'||up==='36'||up==='38'||up==='40') return 'XXL';
      return 'Other';
    }

    function fileToBase64(file){
      return new Promise((resolve,reject)=>{
        const reader = new FileReader();
        reader.onload = ()=>resolve(reader.result.split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });
    }

    async function extractPicklistRows(file){
      const base64 = await fileToBase64(file);
      const mediaType = file.type || (file.name.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'image/png');
      const contentBlock = mediaType === 'application/pdf'
        ? {type:'document', source:{type:'base64', media_type:'application/pdf', data:base64}}
        : {type:'image', source:{type:'base64', media_type:mediaType, data:base64}};
      const response = await fetch('https://api.anthropic.com/v1/messages', {
        method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({
          model:'claude-sonnet-4-6', max_tokens:4000,
          messages:[{role:'user', content:[contentBlock,
            {type:'text', text:'This is a picklist table (columns like SKU, Color, Size, Total Quantity). Extract every data row. Respond with ONLY a JSON array, no markdown fences, no explanation: [{"sku":"...","color":"...","size":"...","qty":1}, ...]. Include rows from all tables on the page.'}
          ]}]
        })
      });
      const data = await response.json();
      const text = (data.content||[]).filter(b=>b.type==='text').map(b=>b.text).join('\n');
      const cleaned = text.replace(/```json/gi,'').replace(/```/g,'').trim();
      const s = cleaned.indexOf('['), e = cleaned.lastIndexOf(']');
      if(s===-1||e===-1) throw new Error('Could not read a table from this file.');
      return JSON.parse(cleaned.slice(s,e+1));
    }

    let szData = [];
    async function runSizeSummary(){
      const errBox = root.querySelector('#sz-errBox'); errBox.innerHTML='';
      const runBtn = root.querySelector('#sz-runBtn');
      const bySku = {};
      function addRow(sku, size, qty){
        const bucket = bucketOf(size);
        if(!bySku[sku]) bySku[sku] = {sku, L:0, XL:0, XXL:0, Other:0, total:0};
        bySku[sku][bucket] += qty; bySku[sku].total += qty;
      }
      try{
        if(activeTab==='csv'){
          if(!ordersFile){ errBox.innerHTML='<div class="error">Please upload the Orders CSV first.</div>'; return; }
          runBtn.disabled=true; runBtn.textContent='Summarizing...';
          const rows = await parseCSVFile(ordersFile);
          const hi = findHeaderRow(rows,[['sku'],['size']]);
          if(hi===-1) throw new Error('Could not find SKU and Size columns.');
          const header = rows[hi];
          const iSku=colIndex(header,['sku']), iSize=colIndex(header,['size']), iQty=colIndex(header,['quantity']);
          rows.slice(hi+1).filter(r=>r.length>=header.length && r[iSku]).forEach(r=>{
            addRow(r[iSku], r[iSize], iQty!==-1 ? (parseInt(r[iQty],10)||1) : 1);
          });
        } else {
          if(picklistFiles.length===0){ errBox.innerHTML='<div class="error">Please add at least one picklist image or PDF.</div>'; return; }
          runBtn.disabled=true; runBtn.textContent='Reading picklists...';
          for(const p of picklistFiles){
            p.status='reading...'; renderPicklistFiles();
            try{ const rows = await extractPicklistRows(p.file); rows.forEach(r=>addRow(r.sku,r.size,parseInt(r.qty,10)||1)); p.status='done'; }
            catch(err){ p.status='error'; }
            renderPicklistFiles();
          }
        }
        szData = Object.values(bySku).sort((a,b)=>b.total-a.total);
        if(szData.length===0) throw new Error('No rows could be read.');
        renderSzResults();
      }catch(err){ errBox.innerHTML='<div class="error">'+err.message+'</div>'; }
      finally{ runBtn.disabled=false; runBtn.textContent='Summarize'; }
    }

    function renderSzResults(){
      root.querySelector('#sz-results').style.display='block';
      const t=k=>szData.reduce((s,r)=>s+r[k],0);
      root.querySelector('#sz-summaryCards').innerHTML = [
        {label:'Total pieces', value:t('total').toLocaleString('en-IN')},
        {label:'L (26-30)', value:t('L').toLocaleString('en-IN')},
        {label:'XL (32-34)', value:t('XL').toLocaleString('en-IN')},
        {label:'XXL (36-40)', value:t('XXL').toLocaleString('en-IN')},
      ].map(c=>`<div class="stat"><div class="label">${c.label}</div><div class="value">${c.value}</div></div>`).join('');

      const cols=[{key:'sku',label:'SKU'},{key:'L',label:'L (26-30)'},{key:'XL',label:'XL (32-34)'},{key:'XXL',label:'XXL (36-40)'},{key:'Other',label:'Other'},{key:'total',label:'Total'}];
      const tbl = sortableTable(
        root.querySelector('#sz-tableHead'), root.querySelector('#sz-tableBody'), root.querySelector('#sz-tableFoot'),
        cols, ()=>szData,
        r=>`<tr><td>${r.sku}</td><td class="num">${r.L}</td><td class="num">${r.XL}</td><td class="num">${r.XXL}</td><td class="num">${r.Other}</td><td class="num">${r.total}</td></tr>`,
        data=>`<td>TOTAL</td><td class="num">${data.reduce((s,r)=>s+r.L,0)}</td><td class="num">${data.reduce((s,r)=>s+r.XL,0)}</td><td class="num">${data.reduce((s,r)=>s+r.XXL,0)}</td><td class="num">${data.reduce((s,r)=>s+r.Other,0)}</td><td class="num">${data.reduce((s,r)=>s+r.total,0)}</td>`,
        {key:'total', dir:-1}
      );
      tbl.draw();
    }

    root.querySelector('#sz-downloadCsv').addEventListener('click', ()=>{
      const rows=[['SKU','L (26-30)','XL (32-34)','XXL (36-40)','Other','Total']];
      szData.forEach(r=>rows.push([r.sku,r.L,r.XL,r.XXL,r.Other,r.total]));
      const csv = rows.map(r=>r.join(',')).join('\n');
      const blob = new Blob([csv],{type:'text/csv'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href=url; a.download='sku_size_summary.csv'; a.click();
      URL.revokeObjectURL(url);
    });

    root.querySelector('#sz-runBtn').addEventListener('click', runSizeSummary);
  })();

  /* =========================================================
     PROFIT & RETURNS TOOL
  ========================================================= */
  (function(){
    let ordersFile = null, returnsFile = null;
    const fnO = root.querySelector('#pf-fnameOrders'), fnR = root.querySelector('#pf-fnameReturns');
    wireDrop(root.querySelector('#pf-dropOrders'), root.querySelector('#pf-fileOrders'), files=>{ ordersFile=files[0]; fnO.textContent=files[0].name; });
    wireDrop(root.querySelector('#pf-dropReturns'), root.querySelector('#pf-fileReturns'), files=>{ returnsFile=files[0]; fnR.textContent=files[0].name; });

    function extractCombo(name){ const m = String(name||'').match(/pack\s*of\s*(\d+)/i); return m ? parseInt(m[1],10) : null; }

    let pfData = [], pfHasReturns=false;

    async function runProfit(){
      const errBox = root.querySelector('#pf-errBox'); errBox.innerHTML='';
      if(!ordersFile){ errBox.innerHTML='<div class="error">Please upload the Orders CSV.</div>'; return; }
      const runBtn = root.querySelector('#pf-runBtn');
      runBtn.disabled=true; runBtn.textContent='Calculating...';
      try{
        const perBlouse = parseFloat(root.querySelector('#pf-pBlouse').value)||0;
        const fixedCost = parseFloat(root.querySelector('#pf-pFixed').value)||0;

        const ordersRows = await parseCSVFile(ordersFile);
        const oHi = findHeaderRow(ordersRows,[['sku'],['product','name'],['reason','credit'],['discounted','price']]);
        if(oHi===-1) throw new Error('Could not find the expected columns (SKU, Product Name, Reason for Credit Entry, Supplier Discounted Price).');
        const oH = ordersRows[oHi];
        const iSku=colIndex(oH,['sku']), iName=colIndex(oH,['product','name']), iStatus=colIndex(oH,['reason','credit']), iSettle=colIndex(oH,['discounted','price']);
        const orderData = ordersRows.slice(oHi+1).filter(r=>r.length>=oH.length && r[iSku]);

        let returnsData=null, rSku=-1, rType=-1;
        if(returnsFile){
          const rRows = await parseCSVFile(returnsFile);
          const rHi = findHeaderRow(rRows,[['sku'],['type','return']]);
          if(rHi!==-1){
            const rH = rRows[rHi];
            rSku = colIndex(rH,['sku']); rType = colIndex(rH,['type','return']);
            returnsData = rRows.slice(rHi+1).filter(r=>r.length>=rH.length && r[rSku]);
          }
        }

        const bySku = {};
        function get(sku){ if(!bySku[sku]) bySku[sku] = {sku, combo:null, totalOrders:0, delivered:0, settlement:0, cost:0, custReturns:0}; return bySku[sku]; }
        const comboBySku = {};
        orderData.forEach(r=>{ const sku=r[iSku]; if(comboBySku[sku]==null){ const c=extractCombo(r[iName]); if(c!=null) comboBySku[sku]=c; } });
        orderData.forEach(r=>{
          const sku=r[iSku]; const rec=get(sku); rec.combo = comboBySku[sku] ?? null; rec.totalOrders+=1;
          const status = String(r[iStatus]||'').trim().toUpperCase();
          if(status==='DELIVERED'){
            rec.delivered+=1;
            const settle = parseFloat(String(r[iSettle]).replace(/[^0-9.\-]/g,''))||0;
            rec.settlement += settle;
            rec.cost += (rec.combo||0)*perBlouse + fixedCost;
          }
        });
        if(returnsData){
          returnsData.forEach(r=>{ const sku=r[rSku]; const type=norm(r[rType]); if(type.includes('customerreturn')){ get(sku).custReturns+=1; } });
        }
        pfHasReturns = returnsData!==null;
        pfData = Object.values(bySku).map(rec=>({...rec, profit: rec.settlement-rec.cost, returnPct: rec.totalOrders>0 ? rec.custReturns/rec.totalOrders*100 : 0})).sort((a,b)=>b.profit-a.profit);
        renderPfResults();
      }catch(err){ errBox.innerHTML='<div class="error">'+err.message+'</div>'; }
      finally{ runBtn.disabled=false; runBtn.textContent='Calculate profit'; }
    }

    function renderPfResults(){
      root.querySelector('#pf-results').style.display='block';
      const totalDelivered = pfData.reduce((s,r)=>s+r.delivered,0);
      const totalOrders = pfData.reduce((s,r)=>s+r.totalOrders,0);
      const totalProfit = pfData.reduce((s,r)=>s+r.profit,0);
      const totalCustReturns = pfData.reduce((s,r)=>s+r.custReturns,0);
      const overallPct = totalOrders>0 ? totalCustReturns/totalOrders*100 : 0;
      const cards = [
        {label:'Delivered orders', value: totalDelivered.toLocaleString('en-IN')},
        {label:'Net profit', value: fmtMoney(totalProfit), cls:'profit'},
        {label:'Avg profit / delivered order', value: fmtMoney(totalDelivered? totalProfit/totalDelivered:0)},
      ];
      if(pfHasReturns) cards.push({label:'Customer return rate', value: overallPct.toFixed(2)+'%', cls: overallPct>15?'warn':''});
      else cards.push({label:'Total orders placed', value: totalOrders.toLocaleString('en-IN')});
      root.querySelector('#pf-summaryCards').innerHTML = cards.map(c=>`<div class="stat ${c.cls||''}"><div class="label">${c.label}</div><div class="value">${c.value}</div></div>`).join('');

      const cols=[{key:'sku',label:'SKU'},{key:'combo',label:'Combo'},{key:'totalOrders',label:'Orders'},{key:'delivered',label:'Delivered'},
        {key:'settlement',label:'Settlement'},{key:'cost',label:'Cost'},{key:'profit',label:'Net Profit'},{key:'custReturns',label:'Returns'},{key:'returnPct',label:'Return %'}];
      const tbl = sortableTable(
        root.querySelector('#pf-tableHead'), root.querySelector('#pf-tableBody'), root.querySelector('#pf-tableFoot'),
        cols, ()=>pfData,
        r=>`<tr><td>${r.sku}</td><td class="num">${r.combo??'—'}</td><td class="num">${r.totalOrders}</td><td class="num">${r.delivered}</td>
          <td class="num">${fmtMoney(r.settlement)}</td><td class="num">${fmtMoney(r.cost)}</td><td class="num ${r.profit<0?'neg':''}">${fmtMoney(r.profit)}</td>
          <td class="num">${pfHasReturns?r.custReturns:'—'}</td><td class="num">${pfHasReturns?r.returnPct.toFixed(2)+'%':'—'}</td></tr>`,
        data=>{
          const t=k=>data.reduce((s,r)=>s+(r[k]||0),0);
          return `<td>TOTAL</td><td></td><td class="num">${t('totalOrders')}</td><td class="num">${t('delivered')}</td>
            <td class="num">${fmtMoney(t('settlement'))}</td><td class="num">${fmtMoney(t('cost'))}</td><td class="num">${fmtMoney(t('profit'))}</td>
            <td class="num">${t('custReturns')}</td><td class="num">${(t('totalOrders')? t('custReturns')/t('totalOrders')*100:0).toFixed(2)}%</td>`;
        },
        {key:'profit', dir:-1}
      );
      tbl.draw();
    }

    root.querySelector('#pf-runBtn').addEventListener('click', runProfit);
  })();

  /* =========================================================
     GST TDS / TCS TOOL
  ========================================================= */
  (function(){
    let portalFiles = [], reportFiles = [];
    const MONTHS = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];
    const GSTIN = /\b\d{2}[A-Z0-9]{13}\b/i;

    function esc(s){ return String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
    function money(n){ return n==null ? '—' : fmtMoney(n); }
    function pct(r){ return (r*100).toFixed(2)+'%'; }
    function isNumCell(c){ return typeof c==='number' || /^\(?-?[₹\s]*[\d,]+(\.\d+)?\)?$/.test(String(c??'').trim()); }
    function num(v){
      if(typeof v==='number') return v;
      const s = String(v??'').trim();
      if(!isNumCell(s)) return NaN;
      const n = parseFloat(s.replace(/[^0-9.\-]/g,''));
      return /^\(.*\)$/.test(s) ? -n : n;
    }

    // ---------- Periods (stored as YYYY-MM) ----------
    function ym(y,m){ return y+'-'+String(m).padStart(2,'0'); }
    function y4(s){ return s.length===2 ? 2000+parseInt(s,10) : parseInt(s,10); }
    function fyStart(v){ const m = String(v??'').match(/(20\d\d)\s*[-\/]\s*(\d{2,4})/); return m ? parseInt(m[1],10) : null; }
    function toPeriod(v, fy){
      let m;
      if(v instanceof Date) return isNaN(v) ? null : ym(v.getFullYear(), v.getMonth()+1);
      if(typeof v==='number' && (m = String(v).match(/^([1-9]|1[0-2])(20\d\d)$/))) return ym(+m[2], +m[1]); // 042025 stored as a number
      if(typeof v==='number' && v>20000 && v<80000){ const d = new Date(Math.round((v-25569)*864e5)); return ym(d.getUTCFullYear(), d.getUTCMonth()+1); }
      const s = String(v??'').trim().toLowerCase();
      if((m = s.match(/^(0[1-9]|1[0-2])(20\d\d)$/))) return ym(+m[2], +m[1]);                    // GST return period: 042025
      if((m = s.match(/^(20\d\d)[-\/.](\d{1,2})\b/)) && +m[2]>=1 && +m[2]<=12) return ym(+m[1], +m[2]); // 2025-04, 2025-04-12
      if((m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d\d|\d\d)\b/))){                       // 12-04-2025 (day first)
        const mo = +m[2]<=12 ? +m[2] : +m[1];
        return mo>=1 && mo<=12 ? ym(y4(m[3]), mo) : null;
      }
      if((m = s.match(/^\d{1,2}[-\s\/]([a-z]{3})[a-z]*[-\s\/,]*(20\d\d|\d\d)\b/)) && MONTHS.includes(m[1])) return ym(y4(m[2]), MONTHS.indexOf(m[1])+1); // 01-Apr-2025
      if((m = s.match(/^([a-z]{3})[a-z]*\.?\s+\d{1,2},?\s+(20\d\d)\b/)) && MONTHS.includes(m[1])) return ym(+m[2], MONTHS.indexOf(m[1])+1);          // Apr 12, 2025
      if((m = s.match(/^([a-z]{3})[a-z]*\.?[\s\-\/,']*(20\d\d|\d\d)?$/)) && MONTHS.includes(m[1])){ // Apr-2025, April 25, April
        const mo = MONTHS.indexOf(m[1])+1;
        if(m[2]) return ym(y4(m[2]), mo);
        if(fy) return ym(mo>=4 ? fy : fy+1, mo);
      }
      return null;
    }
    function periodFromName(name){
      const s = String(name).toLowerCase();
      let m;
      if((m = s.match(/(?:^|\D)(20\d\d)[-_ ]?(0[1-9]|1[0-2])(?!\d)/))) return ym(+m[1], +m[2]);
      if((m = s.match(/(?:^|\D)(0[1-9]|1[0-2])[-_ ]?(20\d\d)(?!\d)/))) return ym(+m[2], +m[1]);
      if((m = s.match(/(?:^|[^a-z])(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*[-_ ]?(20\d\d|\d\d)(?!\d)/))) return ym(y4(m[2]), MONTHS.indexOf(m[1])+1);
      return '';
    }
    function periodLabel(p){ if(!p) return 'No month'; const [y,m] = p.split('-'); return MONTHS[+m-1].replace(/^./,c=>c.toUpperCase())+' '+y; }
    // TCS u/s 52 was cut from 1% to 0.5% on 10 July 2024; TDS u/s 51 is 2%.
    function expectedRate(type, p){
      if(type==='TDS') return [0.02,0.02];
      if(!p) return null;
      return p<'2024-07' ? [0.01,0.01] : p>'2024-07' ? [0.005,0.005] : [0.005,0.01];
    }

    // ---------- Reading tables ----------
    function needXLSX(){ if(typeof XLSX==='undefined') throw new Error('Excel reader did not load — check your internet, or save the file as CSV.'); }
    function readTables(name, bytes){
      if(/\.csv$/i.test(name)) return [{name:'', rows:Papa.parse(new TextDecoder().decode(bytes),{skipEmptyLines:true}).data}];
      needXLSX();
      const wb = XLSX.read(bytes,{type:'array', cellDates:true});
      return wb.SheetNames.map(n=>({name:n, rows:XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1, raw:true, defval:''})}));
    }
    // One source per file; a ZIP (Meesho GST report, GSTR-2A Excel download) gives one source per sheet file inside it.
    async function fileSources(f){
      const bytes = new Uint8Array(await f.arrayBuffer());
      if(!/\.zip$/i.test(f.name)) return [{name:f.name, size:f.size, load:()=>readTables(f.name, bytes)}];
      needXLSX();
      let entries = XLSX.CFB.read(bytes,{type:'array'}).FileIndex.filter(e=>e.type===2 && e.content && /\.(csv|xlsx|xls)$/i.test(e.name));
      if(entries.some(e=>/tcs_sales/i.test(e.name))) entries = entries.filter(e=>/tcs_sales/i.test(e.name)); // Meesho: skip other sheets in the ZIP
      if(!entries.length) throw new Error('no CSV / Excel file inside the ZIP');
      return entries.map(e=>({name:f.name+' › '+e.name, size:e.size, load:()=>readTables(e.name, new Uint8Array(e.content))}));
    }
    // Like colIndex, but skips columns already taken and supports "!token" exclusions.
    function findCol(header, groups, used){
      for(const g of groups){
        const want = g.filter(t=>t[0]!=='!').map(norm), not = g.filter(t=>t[0]==='!').map(t=>norm(t.slice(1)));
        for(let i=0;i<header.length;i++){
          const cell = norm(header[i]);
          if(!used.has(i) && cell && want.every(t=>cell.includes(t)) && !not.some(t=>cell.includes(t))) return i;
        }
      }
      return -1;
    }
    function headerLike(row){
      const cells = (row||[]).filter(c=>String(c??'').trim()!=='');
      return cells.length>0 && !cells.some(c=>c instanceof Date || isNumCell(c) || GSTIN.test(String(c)));
    }
    // Finds the header row that matches the most columns; a second header row
    // (e.g. "Integrated Tax / Central Tax" under a merged "Amount of tax") is merged in.
    function locateHeader(rows, spec, ok){
      let best = null;
      for(let i=0;i<Math.min(rows.length,30);i++){
        const next = rows[i+1]||[], merge = headerLike(next);
        const header = Array.from({length:Math.max(rows[i].length, next.length)}, (_,j)=>String(rows[i][j]??'')+(merge ? ' '+String(next[j]??'') : ''));
        const used = new Set(), cols = {};
        Object.keys(spec).forEach(k=>{ cols[k] = findCol(header, spec[k], used); if(cols[k]>=0) used.add(cols[k]); });
        if(!ok(cols)) continue;
        const score = Object.values(cols).filter(i=>i>=0).length;
        if(!best || score>best.score) best = {cols, header, start:i+(merge?2:1), score};
      }
      return best;
    }
    function isTotalRow(r){ return /^(grand)?total/.test(norm(r.find(x=>String(x??'').trim()!==''))); }

    const PORTAL_COLS = {
      gstin:[['gstin']],
      gross:[['gross']],
      returned:[['returned'],['supplies','return','!period']],
      net:[['net','liable'],['net','amount'],['net','value']],
      taxable:[['taxable'],['amount','paid']],
      igst:[['integrated'],['igst']],
      cgst:[['central'],['cgst']],
      sgst:[['state','tax'],['sgst'],['ut','tax']],
      period:[['tax','period'],['return','period'],['period'],['month']],
      fy:[['financial','year']],
      name:[['trade'],['legal','name'],['name']],
    };
    function nameType(n){ n = norm(n); return n.includes('tcs') && !n.includes('tds') ? 'TCS' : n.includes('tds') && !n.includes('tcs') ? 'TDS' : null; }
    function readPortal(rows, fileName, sheet){
      sheet = String(sheet||'').trim();
      if(/^(tdsa|tcsa)$|amend/i.test(sheet)) return null; // GSTR-2A amendment sheets would double count
      const h = locateHeader(rows, PORTAL_COLS, c=>(c.gross>=0||c.net>=0||c.taxable>=0) && (c.igst>=0||c.cgst>=0||c.gstin>=0));
      if(!h) return null;
      const c = h.cols, joined = norm(h.header.join(' '));
      const tcsHit = /gross|liable|gstr8|operator|ecommerce|collect/.test(joined), tdsHit = /deduct|gstr7/.test(joined);
      const type = tdsHit && !tcsHit ? 'TDS' : tcsHit ? 'TCS' : nameType(sheet) || (/^(sheet\d*)?$/i.test(sheet) ? nameType(fileName) : null);
      if(!type) return null; // e.g. the B2B / CDNR sheets of a GSTR-2A workbook
      const order = type==='TCS' ? [c.net,c.taxable,c.gross] : [c.taxable,c.net,c.gross];
      const amtCol = order.find(i=>i>=0);
      const recs = rows.slice(h.start)
        .filter(r=>isFinite(num(r[amtCol])) && !isTotalRow(r) && (c.gstin<0 || GSTIN.test(String(r[c.gstin]))))
        .map(r=>{
          const v = i=>i>=0 ? (num(r[i])||0) : null;
          const gross = v(c.gross), returned = v(c.returned);
          const net = order[0]>=0 || order[1]>=0 ? v(order[0]>=0 ? order[0] : order[1]) : gross-(returned||0);
          return {
            type, gstin: c.gstin>=0 ? String(r[c.gstin]).trim().toUpperCase() : '', name: c.name>=0 ? String(r[c.name]).trim() : '',
            period: c.period>=0 ? toPeriod(r[c.period], c.fy>=0 ? fyStart(r[c.fy]) : null) : null,
            gross, returned, net, igst:v(c.igst)||0, cgst:v(c.cgst)||0, sgst:v(c.sgst)||0,
          };
        });
      return {type, rows:recs, hasPeriod: recs.every(r=>r.period)};
    }

    const REPORT_COLS = {
      taxable:[['tcs','taxable'],['total','taxable','!shipping'],['taxable','value','!shipping'],['tax','exclusive'],['taxable','!shipping']],
      tax:[['tax','amount','!taxable'],['total','tax','!taxable'],['gst','amount']],
      rate:[['gst','rate'],['tax','rate']],
      month:[['month','number'],['month']],
      fy:[['financial','year']],
      date:[['invoice','date'],['order','date'],['date']],
      type:[['transaction','type'],['event','sub','type'],['event','type']],
    };
    // Month for a report row: month number + financial year (Meesho) first, then the date column.
    function reportPeriod(r, c){
      const od = c.date>=0 ? toPeriod(r[c.date]) : null;
      if(c.month<0) return od;
      const raw = String(r[c.month]??'').trim(), n = /^\d{1,2}$/.test(raw) ? parseInt(raw,10) : NaN;
      if(!(n>=1 && n<=12)) return toPeriod(r[c.month]) || od;
      const fy = c.fy>=0 ? r[c.fy] : '', fs = fyStart(fy);
      if(fs) return ym(n>=4 ? fs : fs+1, n);
      const y = parseInt((String(fy).match(/20\d\d/)||[])[0],10) || (od ? parseInt(od,10) : NaN);
      if(!y) return od;
      // A bare year can be calendar or financial: take the first candidate on/after the order month.
      const cands = [y-1,y,y+1].map(x=>ym(x,n));
      return (od && cands.find(p=>p>=od)) || ym(y,n);
    }
    function readReport(rows){
      const h = locateHeader(rows, REPORT_COLS, c=>c.taxable>=0);
      if(!h) return null;
      const c = h.cols, recs = [];
      rows.slice(h.start).forEach(r=>{
        const value = num(r[c.taxable]);
        if(!isFinite(value) || isTotalRow(r)) return;
        const type = c.type>=0 ? norm(r[c.type]) : '';
        if(type.includes('cancel') && !type.includes('return')) return;
        let tax = c.tax>=0 ? num(r[c.tax]) : NaN;
        if(!isFinite(tax) && c.rate>=0){ const rt = num(r[c.rate])||0; tax = value*(rt>1 ? rt/100 : rt); }
        recs.push({value, tax:isFinite(tax) ? tax : 0, isReturn:/return|refund/.test(type) && !type.includes('cancel'), period:reportPeriod(r,c)});
      });
      return {rows:recs, hasPeriod: recs.every(r=>r.period)};
    }

    // ---------- File lists ----------
    function addSources(list, sources, render, parse){
      sources.forEach(async src=>{
        if(list.some(p=>p.name===src.name && p.size===src.size)) return;
        const item = {name:src.name, size:src.size, status:'reading...', month:'month' in src ? src.month : periodFromName(src.name), role:/return/i.test(src.name) ? 'returns' : 'sales'};
        list.push(item); render();
        try{
          const tables = (await src.load()).map(t=>parse(t.rows, src.name, t.name)).filter(t=>t && t.rows.length);
          if(!tables.length) throw new Error('no matching table found');
          item.tables = tables; item.hasPeriod = tables.every(t=>t.hasPeriod);
          item.status = describe(tables);
        }catch(err){ item.error = true; item.status = err.message; }
        render();
      });
    }
    async function addFiles(list, files, render, parse){
      for(const f of Array.from(files)){
        try{ addSources(list, await fileSources(f), render, parse); }
        catch(err){ list.push({name:f.name, size:f.size, error:true, status:err.message}); render(); }
      }
    }
    function describe(tables){
      const months = new Set(), counts = {};
      tables.forEach(t=>{ counts[t.type||'rows'] = (counts[t.type||'rows']||0)+t.rows.length; t.rows.forEach(r=>{ if(r.period) months.add(r.period); }); });
      const m = [...months].sort();
      const span = m.length ? ' · '+periodLabel(m[0])+(m.length>1 ? ' – '+periodLabel(m[m.length-1]) : '') : '';
      return Object.entries(counts).map(([k,n])=>k==='rows' ? n.toLocaleString('en-IN')+' rows' : k+' · '+n+' row'+(n>1?'s':'')).join(', ')+span;
    }
    function bindList(listEl, list, render){
      listEl.querySelectorAll('[data-month]').forEach(el=>el.addEventListener('change', ()=>{ list[+el.getAttribute('data-month')].month = el.value; el.classList.toggle('need', !el.value); }));
      listEl.querySelectorAll('[data-role]').forEach(el=>el.addEventListener('change', ()=>{ list[+el.getAttribute('data-role')].role = el.value; }));
      listEl.querySelectorAll('.remove').forEach(el=>el.addEventListener('click', ()=>{ list.splice(+el.getAttribute('data-i'),1); render(); }));
    }
    function monthInput(p,i){
      return p.tables && !p.hasPeriod ? `<input type="month" data-month="${i}" value="${p.month}" class="${p.month?'':'need'}" title="Month for rows without a tax period / date" />` : '';
    }
    const portalListEl = root.querySelector('#gst-portalFiles'), reportListEl = root.querySelector('#gst-reportFiles');
    function renderPortalFiles(){
      portalListEl.innerHTML = portalFiles.map((p,i)=>`
        <div class="fileitem"><span>${esc(p.name)}</span><span class="ctl">
          <span class="status ${p.error?'err':p.tables?'done':''}">${esc(p.status)}</span>${monthInput(p,i)}
          <span class="remove" data-i="${i}">&times;</span></span></div>`).join('');
      bindList(portalListEl, portalFiles, renderPortalFiles);
    }
    function renderReportFiles(){
      reportListEl.innerHTML = reportFiles.map((p,i)=>`
        <div class="fileitem"><span>${esc(p.name)}</span><span class="ctl">
          <select data-role="${i}"><option value="sales"${p.role==='sales'?' selected':''}>Sales</option><option value="returns"${p.role==='returns'?' selected':''}>Returns</option></select>
          <span class="status ${p.error?'err':p.tables?'done':''}">${esc(p.status)}</span>${monthInput(p,i)}
          <span class="remove" data-i="${i}">&times;</span></span></div>`).join('');
      bindList(reportListEl, reportFiles, renderReportFiles);
    }
    const portalInput = root.querySelector('#gst-filePortal'), reportInput = root.querySelector('#gst-fileReports');
    wireDrop(root.querySelector('#gst-dropPortal'), portalInput, files=>{ addFiles(portalFiles, files, renderPortalFiles, readPortal); portalInput.value=''; });
    wireDrop(root.querySelector('#gst-dropReports'), reportInput, files=>{ addFiles(reportFiles, files, renderReportFiles, readReport); reportInput.value=''; });
    // Tables read straight off the portal page by the browser extension (gst-extension/).
    document.addEventListener('gst:captured', e=>{
      const d = e.detail||{};
      addSources(portalFiles, [{name:d.name, size:d.at, month:toPeriod(d.month, fyStart(d.fy))||'', load:()=>(d.tables||[]).map(rows=>({name:'', rows}))}], renderPortalFiles, readPortal); // size: capture time, so two captures never look alike
    });

    // ---------- Calculation ----------
    let gstPortal = [], gstReports = {}, gstTol = 10, gstRate = 0.05, ecoSel = 'all';

    function runGst(){
      const errBox = root.querySelector('#gst-errBox'); errBox.innerHTML='';
      gstTol = Math.abs(parseFloat(root.querySelector('#gst-pTol').value)||0);
      gstRate = (parseFloat(root.querySelector('#gst-pRate').value)||0)/100;
      try{
        if(portalFiles.some(p=>!p.tables && !p.error) || reportFiles.some(p=>!p.tables && !p.error)) throw new Error('Files are still being read — try again in a moment.');
        const recs = [];
        portalFiles.forEach(f=>(f.tables||[]).forEach(t=>t.rows.forEach(r=>recs.push({...r, period:r.period||f.month||''}))));
        const pasted = root.querySelector('#gst-paste').value.trim();
        if(pasted){
          const t = readPortal(Papa.parse(pasted,{skipEmptyLines:true, delimiter:pasted.includes('\t') ? '\t' : ''}).data, '', '');
          if(!t || !t.rows.length) throw new Error('Could not read the pasted table — include the header row (GSTIN, gross / net value, tax columns).');
          const month = root.querySelector('#gst-pasteMonth').value;
          t.rows.forEach(r=>recs.push({...r, period:r.period||month||''}));
        }
        if(!recs.length) throw new Error('Please add the GST portal TDS / TCS file (or paste the table) first.');

        // One line per credit type + operator/deductor + month (POS-wise rows are added together).
        const by = {};
        recs.forEach(r=>{
          const k = r.type+'|'+r.gstin+'|'+r.period;
          const a = by[k] || (by[k] = {type:r.type, gstin:r.gstin, name:r.name, period:r.period, gross:null, returned:null, net:0, igst:0, cgst:0, sgst:0});
          if(r.gross!=null) a.gross = (a.gross||0)+r.gross;
          if(r.returned!=null) a.returned = (a.returned||0)+r.returned;
          a.net += r.net; a.igst += r.igst; a.cgst += r.cgst; a.sgst += r.sgst;
          if(!a.name) a.name = r.name;
        });
        gstPortal = Object.values(by).map(a=>{
          const tax = a.igst+a.cgst+a.sgst, rate = expectedRate(a.type, a.period), issues = [];
          const inter = tax ? a.net*a.igst/tax : null;
          if(a.gross!=null && a.returned!=null && Math.abs(a.gross-a.returned-a.net)>gstTol) issues.push('Net ≠ gross − returned');
          if(rate && (tax<a.net*rate[0]-gstTol || tax>a.net*rate[1]+gstTol)) issues.push('Rate '+pct(a.net ? tax/a.net : 0)+' (expected '+(rate[0]===rate[1] ? pct(rate[0]) : pct(rate[0])+'–'+pct(rate[1]))+')');
          return {...a, tax, inter, intra: inter==null ? null : a.net-inter, effRate: a.net ? tax/a.net : 0, check: issues.join('; ') || 'OK'};
        }).sort((x,y)=>x.period.localeCompare(y.period) || x.type.localeCompare(y.type) || x.name.localeCompare(y.name));

        gstReports = {};
        reportFiles.forEach(f=>(f.tables||[]).forEach(t=>t.rows.forEach(r=>{
          const p = r.period||f.month||'';
          const m = gstReports[p] || (gstReports[p] = {sales:0, returns:0, tax:0});
          if(f.role==='returns' || r.value<0 || r.isReturn){ m.returns += Math.abs(r.value); m.tax -= Math.abs(r.tax); }
          else { m.sales += r.value; m.tax += r.tax; }
        })));

        const ecos = {};
        gstPortal.filter(a=>a.type==='TCS').forEach(a=>{ ecos[a.gstin] = a.name || a.gstin || 'Operator'; });
        if(ecoSel!=='all' && !(ecoSel in ecos)) ecoSel = 'all';
        root.querySelector('#gst-eco').innerHTML = '<option value="all">All e-commerce operators</option>'+Object.entries(ecos).map(([g,n])=>`<option value="${esc(g)}"${g===ecoSel?' selected':''}>${esc(n)}${g?' ('+esc(g)+')':''}</option>`).join('');
        root.querySelector('#gst-ecoField').classList.toggle('hidden', Object.keys(ecos).length<2);

        const noMonth = gstPortal.some(a=>!a.period) || ('' in gstReports);
        if(noMonth) errBox.innerHTML = '<div class="warnbox">Some rows have no month (shown as "No month"). Set the month next to the file to place them correctly.</div>';
        renderGstResults();
      }catch(err){ errBox.innerHTML='<div class="error">'+esc(err.message)+'</div>'; }
    }

    function matchRows(){
      const portal = {};
      gstPortal.filter(a=>a.type==='TCS' && (ecoSel==='all' || a.gstin===ecoSel)).forEach(a=>{
        const m = portal[a.period] || (portal[a.period] = {gross:0, returned:0, net:0, tax:0, hasGross:false});
        m.gross += a.gross||0; m.returned += a.returned||0; m.net += a.net; m.tax += a.tax; m.hasGross = m.hasGross || a.gross!=null;
      });
      const months = [...new Set([...Object.keys(portal), ...Object.keys(gstReports)])].sort();
      return months.map(period=>{
        const p = portal[period], r = gstReports[period], rate = expectedRate('TCS', period);
        const rNet = r ? r.sales-r.returns : null;
        const diff = p && r ? p.net-rNet : null;
        let status = 'Matched';
        if(!p) status = 'Not in portal';
        else if(!r) status = 'No report';
        else if(Math.abs(diff)>gstTol) status = 'Value mismatch';
        else if(rate && (p.tax<rNet*rate[0]-gstTol || p.tax>rNet*rate[1]+gstTol)) status = 'TCS mismatch';
        return {
          period, pGross:p && p.hasGross ? p.gross : null, rSales:r ? r.sales : null, pReturned:p && p.hasGross ? p.returned : null, rReturns:r ? r.returns : null,
          pNet:p ? p.net : null, rNet, diff, pTax:p ? p.tax : null, eTax:r && rate ? rNet*(rate[0]+rate[1])/2 : null,
          eTaxLabel:r && rate ? (rate[0]===rate[1] ? fmtMoney(rNet*rate[0]) : fmtMoney(rNet*rate[0])+'–'+fmtMoney(rNet*rate[1])) : '—',
          rTax:r ? r.tax : null, status,
        };
      });
    }

    function cards(el, list){ el.innerHTML = list.map(c=>`<div class="stat ${c.cls||''}"><div class="label">${c.label}</div><div class="value">${c.value}</div></div>`).join(''); }

    function renderGstResults(){
      root.querySelector('#gst-results').style.display='block';
      const sum = (rows,k)=>rows.reduce((s,r)=>s+(r[k]||0),0);
      const tcs = gstPortal.filter(a=>a.type==='TCS'), tds = gstPortal.filter(a=>a.type==='TDS');
      cards(root.querySelector('#gst-portalCards'), [
        {label:'TCS taxable value (net)', value:fmtMoney(sum(tcs,'net')), cls:'profit'},
        {label:'TCS credit', value:fmtMoney(sum(tcs,'tax'))},
        {label:'TDS taxable value', value:fmtMoney(sum(tds,'net')), cls:'profit'},
        {label:'TDS credit', value:fmtMoney(sum(tds,'tax'))},
      ]);
      const inter = sum(gstPortal,'inter'), intra = sum(gstPortal,'intra'), rateLbl = +(gstRate*100).toFixed(2)+'%';
      cards(root.querySelector('#gst-splitCards'), [
        {label:'Inter-state taxable (IGST)', value:fmtMoney(inter)},
        {label:'Intra-state taxable (CGST+SGST)', value:fmtMoney(intra)},
        {label:'Est. IGST payable @ '+rateLbl, value:fmtMoney(inter*gstRate)},
        {label:'Est. CGST & SGST payable (each)', value:fmtMoney(intra*gstRate/2)},
      ]);

      const pCols=[{key:'type',label:'Type'},{key:'name',label:'Operator / Deductor'},{key:'period',label:'Month'},{key:'gross',label:'Gross value'},{key:'returned',label:'Returned'},
        {key:'net',label:'Net taxable'},{key:'inter',label:'Inter-state'},{key:'intra',label:'Intra-state'},{key:'tax',label:'Credit (tax)'},{key:'effRate',label:'Rate'},{key:'check',label:'Check'}];
      sortableTable(
        root.querySelector('#gst-portalHead'), root.querySelector('#gst-portalBody'), root.querySelector('#gst-portalFoot'),
        pCols, ()=>gstPortal,
        r=>`<tr><td>${r.type}</td><td>${esc(r.name||'—')}<span class="gstin">${esc(r.gstin)}</span></td><td>${periodLabel(r.period)}</td>
          <td class="num">${money(r.gross)}</td><td class="num">${money(r.returned)}</td><td class="num">${fmtMoney(r.net)}</td>
          <td class="num">${money(r.inter)}</td><td class="num">${money(r.intra)}</td><td class="num">${fmtMoney(r.tax)}</td>
          <td class="num">${pct(r.effRate)}</td><td class="${r.check==='OK'?'ok':'bad'}">${esc(r.check)}</td></tr>`,
        data=>`<td>TOTAL</td><td></td><td></td><td class="num">${fmtMoney(sum(data,'gross'))}</td><td class="num">${fmtMoney(sum(data,'returned'))}</td>
          <td class="num">${fmtMoney(sum(data,'net'))}</td><td class="num">${fmtMoney(sum(data,'inter'))}</td><td class="num">${fmtMoney(sum(data,'intra'))}</td>
          <td class="num">${fmtMoney(sum(data,'tax'))}</td><td></td><td>${data.filter(r=>r.check!=='OK').length} to check</td>`,
        {key:'period', dir:1}
      ).draw();

      const hasReports = Object.keys(gstReports).length>0;
      root.querySelector('#gst-matchSection').classList.toggle('hidden', !hasReports);
      if(hasReports) renderMatch();
    }

    function renderMatch(){
      const rows = matchRows(), sum = k=>rows.reduce((s,r)=>s+(r[k]||0),0);
      const both = rows.filter(r=>r.diff!=null), matched = rows.filter(r=>r.status==='Matched').length, diff = sum('diff');
      cards(root.querySelector('#gst-matchCards'), [
        {label:'Reports net taxable', value:fmtMoney(sum('rNet')), cls:'profit'},
        {label:'Portal − reports (common months)', value:fmtMoney(diff), cls:Math.abs(diff)>gstTol?'warn':''},
        {label:'Months matched (in both)', value:matched+' / '+both.length, cls:matched<both.length?'warn':''},
        {label:'GST in reports (net)', value:fmtMoney(sum('rTax'))},
      ]);
      const mCols=[{key:'period',label:'Month'},{key:'pGross',label:'Portal gross'},{key:'rSales',label:'Report sales'},{key:'pReturned',label:'Portal returned'},{key:'rReturns',label:'Report returns'},
        {key:'pNet',label:'Portal net'},{key:'rNet',label:'Report net'},{key:'diff',label:'Difference'},{key:'pTax',label:'Portal TCS'},{key:'eTax',label:'Expected TCS'},{key:'status',label:'Status'}];
      sortableTable(
        root.querySelector('#gst-matchHead'), root.querySelector('#gst-matchBody'), root.querySelector('#gst-matchFoot'),
        mCols, ()=>rows,
        r=>`<tr><td>${periodLabel(r.period)}</td><td class="num">${money(r.pGross)}</td><td class="num">${money(r.rSales)}</td><td class="num">${money(r.pReturned)}</td><td class="num">${money(r.rReturns)}</td>
          <td class="num">${money(r.pNet)}</td><td class="num">${money(r.rNet)}</td><td class="num ${r.diff!=null && Math.abs(r.diff)>gstTol?'neg':''}">${money(r.diff)}</td>
          <td class="num">${money(r.pTax)}</td><td class="num">${r.eTaxLabel}</td><td class="${r.status==='Matched'?'ok':'bad'}">${r.status}</td></tr>`,
        data=>`<td>TOTAL</td><td class="num">${fmtMoney(sum('pGross'))}</td><td class="num">${fmtMoney(sum('rSales'))}</td><td class="num">${fmtMoney(sum('pReturned'))}</td><td class="num">${fmtMoney(sum('rReturns'))}</td>
          <td class="num">${fmtMoney(sum('pNet'))}</td><td class="num">${fmtMoney(sum('rNet'))}</td><td class="num">${fmtMoney(both.reduce((s,r)=>s+r.diff,0))}</td>
          <td class="num">${fmtMoney(sum('pTax'))}</td><td></td><td>${matched} matched</td>`,
        {key:'period', dir:1}
      ).draw();
    }

    root.querySelector('#gst-eco').addEventListener('change', e=>{ ecoSel = e.target.value; renderMatch(); });
    root.querySelector('#gst-download').addEventListener('click', ()=>{
      const r2 = n=>n==null ? '' : Math.round(n*100)/100;
      const a = [['Type','GSTIN','Name','Month','Gross value','Value returned','Net taxable','Inter-state taxable','Intra-state taxable','IGST','CGST','SGST','Total tax','Rate %','Check']];
      gstPortal.forEach(r=>a.push([r.type,r.gstin,r.name,r.period,r2(r.gross),r2(r.returned),r2(r.net),r2(r.inter),r2(r.intra),r2(r.igst),r2(r.cgst),r2(r.sgst),r2(r.tax),r2(r.effRate*100),r.check]));
      let csv = Papa.unparse(a);
      if(Object.keys(gstReports).length){
        const b = [['Month','Portal gross','Report sales','Portal returned','Report returns','Portal net taxable','Report net taxable','Difference','Portal TCS','Expected TCS','Report GST','Status']];
        matchRows().forEach(r=>b.push([r.period,r2(r.pGross),r2(r.rSales),r2(r.pReturned),r2(r.rReturns),r2(r.pNet),r2(r.rNet),r2(r.diff),r2(r.pTax),r2(r.eTax),r2(r.rTax),r.status]));
        csv += '\n\n'+Papa.unparse(b);
      }
      const blob = new Blob([csv],{type:'text/csv'});
      const url = URL.createObjectURL(blob);
      const el = document.createElement('a'); el.href=url; el.download='gst_tds_tcs_reconciliation.csv'; el.click();
      URL.revokeObjectURL(url);
    });
    root.querySelector('#gst-runBtn').addEventListener('click', runGst);
  })();

})();
